-- Operator workflow is independent of response admission and respondent data.
CREATE TABLE submission_statuses (
 id TEXT PRIMARY KEY, flow_id TEXT NOT NULL REFERENCES flows(id) ON DELETE CASCADE,
 name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 60), created_at TEXT NOT NULL
);
CREATE UNIQUE INDEX submission_status_name ON submission_statuses(flow_id,lower(name));
CREATE TABLE submission_workflows (
 response_id TEXT PRIMARY KEY REFERENCES responses(id) ON DELETE CASCADE,
 status_id TEXT NOT NULL DEFAULT 'new', assignee_id TEXT REFERENCES operators(id) ON DELETE SET NULL,
 version INTEGER NOT NULL CHECK(version>=1), updated_at TEXT NOT NULL
);
CREATE INDEX submission_workflow_status ON submission_workflows(status_id,response_id);
CREATE INDEX submission_workflow_assignee ON submission_workflows(assignee_id,response_id);
CREATE TABLE submission_tags (
 response_id TEXT NOT NULL REFERENCES responses(id) ON DELETE CASCADE,
 tag TEXT NOT NULL CHECK(length(tag) BETWEEN 1 AND 40), PRIMARY KEY(response_id,tag)
);
CREATE INDEX submission_tag_lookup ON submission_tags(tag,response_id);
CREATE TABLE submission_notes (
 id TEXT PRIMARY KEY, response_id TEXT NOT NULL REFERENCES responses(id) ON DELETE CASCADE,
 text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 2000), author_id TEXT REFERENCES operators(id) ON DELETE SET NULL,
 created_at TEXT NOT NULL
);
CREATE INDEX submission_note_page ON submission_notes(response_id,created_at,id);
-- Empty outside a transaction. Failed assertions roll back every mutation and audit event.
CREATE TABLE submission_write_assertions (ok INTEGER NOT NULL CONSTRAINT submission_write_valid CHECK(ok=1));
CREATE TRIGGER IF NOT EXISTS form_import_epoch_submission_statuses_insert BEFORE INSERT ON submission_statuses BEGIN SELECT RAISE(ABORT,'IMPORT_NATIVE_PUBLICATION_CHANGED') WHERE EXISTS(SELECT 1 FROM form_import_native_publication_fences WHERE target_id IN (SELECT NEW.flow_id AS target_id)); UPDATE form_import_native_clock SET revision=revision+1 WHERE id=1 AND EXISTS(SELECT target_id FROM (SELECT NEW.flow_id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)); INSERT INTO form_import_native_epochs(target_id,revision) SELECT target_id,(SELECT revision FROM form_import_native_clock WHERE id=1) FROM (SELECT target_id FROM (SELECT NEW.flow_id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)) WHERE 1 ON CONFLICT(target_id) DO UPDATE SET revision=excluded.revision; END;
