CREATE TRIGGER reporting_submission_workflows_insert AFTER INSERT ON submission_workflows BEGIN
 UPDATE reporting_generations SET generation=generation+1 WHERE workspace_id IN(SELECT workspace_id FROM (SELECT workspace_id,flow_id FROM responses WHERE id IN(SELECT NEW.response_id)));
 INSERT INTO reporting_changes(workspace_id,flow_id,eligible_at,generation)
 SELECT c.workspace_id,c.flow_id,'0000',g.generation FROM (SELECT workspace_id,flow_id FROM responses WHERE id IN(SELECT NEW.response_id)) c JOIN reporting_generations g ON g.workspace_id=c.workspace_id WHERE 1
 ON CONFLICT(workspace_id,flow_id,eligible_at) DO UPDATE SET generation=excluded.generation;
END;
